// Group tasks by day number
export const DAYS_MAP = DAYS.reduce((acc, task) => {
  if (!acc[task.day]) acc[task.day] = [];
  acc[task.day].push(task);
  return acc;
}, {});

export const TOTAL_DAYS = 84;

export function getDayPoints(tasks) {
  return tasks.reduce((sum, t) => sum + (CATEGORY_POINTS[t.category] || 1), 0);
}

export function getMonth(day) {
  if (day <= 28) return 1;
  if (day <= 56) return 2;
  return 3;
}